CREATE OR REPLACE FUNCTION public.deduct_ticket_and_confirm_booking(p_learner_id uuid, p_booking_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor_id uuid := auth.uid();
  v_profile_id uuid;
  v_tickets integer;
  v_status text;
  v_deducted boolean;
  v_slot_id uuid;
  v_booking_learner uuid;
  v_booking_partner uuid;
  v_booking_partner_user uuid;
  v_slot_partner uuid;
  v_slot_status text;
  v_slot_time text;
  v_scheduled_at timestamptz;
  v_allocation_id uuid;
  v_allocated_owner uuid;
  v_lot_id uuid;
begin
  if v_actor_id is null then
    return pg_catalog.jsonb_build_object('success', false, 'message', '濡쒓렇?몄씠 ?꾩슂?⑸땲??');
  end if;

  if p_learner_id is null
     or p_booking_id is null
     or p_learner_id <> v_actor_id then
    return pg_catalog.jsonb_build_object('success', false, 'message', '?숈뒿??蹂몄씤留??덉빟???뺤젙?????덉뒿?덈떎.');
  end if;

  select learner_id, partner_id, partner_user_id, slot_id, status, ticket_deducted
    into v_booking_learner, v_booking_partner, v_booking_partner_user,
         v_slot_id, v_status, v_deducted
    from public.bookings
   where id = p_booking_id
   for update;

  if not found then
    return pg_catalog.jsonb_build_object('success', false, 'message', '?ㅼ젣 ?덉빟 ID瑜?李얠쓣 ???놁뒿?덈떎.');
  end if;

  if v_booking_learner is null or v_booking_learner <> v_actor_id then
    return pg_catalog.jsonb_build_object('success', false, 'message', '?덉빟 ?뚯쑀?먭? ?쇱튂?섏? ?딆뒿?덈떎.');
  end if;

  if v_status in ('confirmed', 'completed') then
    if not coalesce(v_deducted, false) then
      raise exception 'Confirmed booking has no ticket deduction.' using errcode = '23514';
    end if;

    select a.id, l.user_id
      into v_allocation_id, v_allocated_owner
      from public.ticket_allocations a
      join public.ticket_lots l on l.id = a.ticket_lot_id
     where a.booking_id = p_booking_id
     for update of a;

    if v_allocation_id is null then
      if not exists (
        select 1 from public.ticket_consumption_pre_cutover_bookings
         where booking_id = p_booking_id
      ) then
        raise exception 'Confirmed booking has no ticket allocation.' using errcode = '23514';
      end if;
    elsif v_allocated_owner <> v_actor_id then
      raise exception 'Booking ticket allocation belongs to another user.' using errcode = '23514';
    end if;

    select ticket_count into v_tickets
      from public.profiles where id = v_actor_id;
    return pg_catalog.jsonb_build_object(
      'success', true, 'remaining_tickets', v_tickets,
      'message', '?대? ?뺤젙???덉빟?낅땲??'
    );
  end if;

  if v_status <> 'pending' then
    return pg_catalog.jsonb_build_object('success', false, 'remaining_tickets', v_tickets,
      'message', '?뺤젙?????덈뒗 ?덉빟 ?곹깭媛 ?꾨떃?덈떎.');
  end if;

  if coalesce(v_deducted, false) then
    raise exception 'Pending booking already has a ticket deduction.' using errcode = '23514';
  end if;

  -- 049's trigger also enforces this at the status update. Check early so
  -- ordinary users cannot consume a lot while pre-open booking is disabled.

  if v_slot_id is null then
    return pg_catalog.jsonb_build_object('success', false, 'remaining_tickets', v_tickets,
      'message', '?덉빟 ?쒓컙 ?뺣낫瑜??뺤씤?????놁뒿?덈떎.');
  end if;

  if v_booking_partner is null
     or v_booking_partner_user is null
     or v_booking_partner <> v_booking_partner_user then
    return pg_catalog.jsonb_build_object('success', false, 'remaining_tickets', v_tickets,
      'message', '?덉빟 ?뚰듃???뺣낫媛 ?쇱튂?섏? ?딆뒿?덈떎.');
  end if;

  select partner_id, status, slot_time
    into v_slot_partner, v_slot_status, v_slot_time
    from public.availability_slots
   where id = v_slot_id
   for update;

  if not found then
    return pg_catalog.jsonb_build_object('success', false, 'remaining_tickets', v_tickets,
      'message', '?덉빟 ?쒓컙??李얠쓣 ???놁뒿?덈떎.');
  end if;

  if v_slot_status <> 'available' then
    return pg_catalog.jsonb_build_object('success', false, 'remaining_tickets', v_tickets,
      'message', '?대? ?덉빟?섏뿀嫄곕굹 ?좏깮?????녿뒗 ?쒓컙?낅땲??');
  end if;

  if v_slot_partner <> v_booking_partner_user then
    return pg_catalog.jsonb_build_object('success', false, 'remaining_tickets', v_tickets,
      'message', '?덉빟 ?쒓컙???뚰듃???뺣낫媛 ?쇱튂?섏? ?딆뒿?덈떎.');
  end if;

  v_slot_time := pg_catalog.btrim(v_slot_time);

  if v_slot_time is null or v_slot_time = '' then
    return pg_catalog.jsonb_build_object('success', false, 'remaining_tickets', v_tickets,
      'message', '?덉빟 ?쒓컙 ?뺤떇???뺤씤?????놁뒿?덈떎.');
  end if;

  if v_slot_time like 'weekly:%' then
    return pg_catalog.jsonb_build_object('success', false, 'remaining_tickets', v_tickets,
      'message', '諛섎났 媛?μ떆媛??쒗뵆由우? ?ㅼ젣 ?덉빟???ъ슜?????놁뒿?덈떎.');
  end if;

  if v_slot_time !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ]' then
    return pg_catalog.jsonb_build_object('success', false, 'remaining_tickets', v_tickets,
      'message', '?덉빟 ?쒓컙 ?뺤떇???뺤씤?????놁뒿?덈떎.');
  end if;

  begin
    if v_slot_time ~* '(Z|[+-][0-9]{2}(:[0-9]{2}|[0-9]{2})?)$' then
      v_scheduled_at := v_slot_time::timestamptz;
    else
      v_scheduled_at := v_slot_time::timestamp at time zone 'Asia/Seoul';
    end if;
  exception when others then
    return pg_catalog.jsonb_build_object('success', false, 'remaining_tickets', v_tickets,
      'message', '?덉빟 ?쒓컙 ?뺤떇???뺤씤?????놁뒿?덈떎.');
  end;

  -- Check the booking allocation before selecting a lot. A pending booking
  -- with an allocation is inconsistent, never an idempotent confirmation.
  select id into v_allocation_id
    from public.ticket_allocations
   where booking_id = p_booking_id
   for update;
  if found then
    raise exception 'Pending booking already has a ticket allocation.' using errcode = '23514';
  end if;

  -- Issuance locks the profile before touching lots. Taking the same lock
  -- before the FIFO lot prevents grant/consumption deadlocks and double spend.
  select id into v_profile_id
    from public.profiles
   where id = v_actor_id
   for update;
  if not found then
    return pg_catalog.jsonb_build_object('success', false, 'message', '?꾨줈?꾩쓣 李얠쓣 ???놁뒿?덈떎.');
  end if;

  select id into v_lot_id
    from public.ticket_lots
   where user_id = v_actor_id
     and quantity_remaining > 0
     and (expires_at is null or expires_at > pg_catalog.now())
   order by expires_at asc nulls last, issued_at asc nulls last, id asc
   limit 1
   for update;

  if v_lot_id is null then
    return pg_catalog.jsonb_build_object('success', false, 'remaining_tickets', 0,
      'message', '蹂댁쑀 ?곗폆??遺議깊빀?덈떎.');
  end if;

  update public.ticket_lots
     set quantity_remaining = quantity_remaining - 1,
         updated_at = pg_catalog.now()
   where id = v_lot_id
     and user_id = v_actor_id
     and quantity_remaining > 0
     and (expires_at is null or expires_at > pg_catalog.now());
  if not found then
    raise exception 'Ticket lot changed while confirming the booking.' using errcode = '40001';
  end if;

  insert into public.ticket_allocations (booking_id, ticket_lot_id, quantity)
  values (p_booking_id, v_lot_id, 1);

  v_tickets := public.refresh_ticket_balance_cache(v_actor_id);

  update public.bookings
     set status = 'confirmed',
         ticket_deducted = true,
         scheduled_at = v_scheduled_at,
         updated_at = pg_catalog.now()
   where id = p_booking_id
     and learner_id = v_actor_id
     and status = 'pending'
     and ticket_deducted = false;
  if not found then
    raise exception 'Booking confirmation state changed while deducting a ticket.'
      using errcode = '40001';
  end if;

  update public.availability_slots
     set status = 'booked',
         updated_at = pg_catalog.now()
   where id = v_slot_id
     and partner_id = v_booking_partner_user
     and status = 'available';
  if not found then
    raise exception 'Availability slot state changed while confirming the booking.'
      using errcode = '40001';
  end if;

  return pg_catalog.jsonb_build_object(
    'success', true,
    'remaining_tickets', v_tickets,
    'message', '?덉빟???뺤젙?섏뿀?듬땲??'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.deduct_ticket_and_confirm_booking(p_learner_id uuid, p_booking_id uuid, p_slot_id uuid, p_partner_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor_id uuid := auth.uid();
  v_slot_id uuid;
  v_partner_id uuid;
begin
  if v_actor_id is null or p_learner_id is null or p_learner_id <> v_actor_id then
    return pg_catalog.jsonb_build_object('success', false,
      'message', '?숈뒿??蹂몄씤留??덉빟???뺤젙?????덉뒿?덈떎.');
  end if;

  select slot_id, partner_user_id
    into v_slot_id, v_partner_id
    from public.bookings
   where id = p_booking_id
     and learner_id = v_actor_id
   for update;

  if found then
    if p_slot_id is not null and p_slot_id is distinct from v_slot_id then
      return pg_catalog.jsonb_build_object('success', false,
        'message', '?덉빟 ?쒓컙 ?뺣낫媛 ?쇱튂?섏? ?딆뒿?덈떎.');
    end if;
    if p_partner_id is not null and p_partner_id is distinct from v_partner_id then
      return pg_catalog.jsonb_build_object('success', false,
        'message', '?덉빟 ?뚰듃???뺣낫媛 ?쇱튂?섏? ?딆뒿?덈떎.');
    end if;
  end if;

  return public.deduct_ticket_and_confirm_booking(p_learner_id, p_booking_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_my_booking(p_booking_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor_id uuid := auth.uid();
  v_now timestamptz := pg_catalog.now();
  v_booking public.bookings%rowtype;
  v_slot public.availability_slots%rowtype;
  v_allocation public.ticket_allocations%rowtype;
  v_lot public.ticket_lots%rowtype;
  v_early boolean;
  v_ticket_count integer;
  v_partner_points integer;
begin
  if v_actor_id is null or p_booking_id is null then
    raise exception 'Login and booking ID are required.' using errcode = '42501';
  end if;

  select * into v_booking
    from public.bookings
   where id = p_booking_id
   for update;
  if not found or v_booking.learner_id is distinct from v_actor_id then
    raise exception 'Learner booking access is required.' using errcode = '42501';
  end if;

  -- Every post-cutover confirmed booking must have precisely one allocation.
  -- Do not invent a scalar or historical refund for missing allocations.
  select * into v_allocation
    from public.ticket_allocations
   where booking_id = p_booking_id
   for update;
  if not found or v_allocation.quantity is distinct from 1
     or v_booking.ticket_deducted is distinct from true then
    raise exception 'Booking ticket allocation is inconsistent.' using errcode = '23514';
  end if;

  select * into v_lot
    from public.ticket_lots
   where id = v_allocation.ticket_lot_id;
  if not found or v_lot.user_id is distinct from v_actor_id then
    raise exception 'Booking allocation belongs to another ticket owner.' using errcode = '23514';
  end if;

  if v_booking.status = 'cancelled' then
    if v_booking.end_reason = 'user_cancelled_early'
       and v_booking.ticket_refunded is true
       and v_allocation.refunded_at is not null
       and v_allocation.refund_reason = 'user_cancelled_early'
       and v_booking.partner_rewarded is false
       and v_booking.ended_at is not null
       and v_booking.completed_at is null then
      return pg_catalog.jsonb_build_object(
        'success', true, 'already_cancelled', true,
        'cancellation_type', 'early', 'ticket_refunded', true,
        'partner_rewarded', false
      );
    elsif v_booking.end_reason = 'user_cancelled_late'
       and v_booking.ticket_refunded is false
       and v_allocation.refunded_at is null
       and v_allocation.refund_reason is null
       and v_booking.partner_rewarded is true
       and v_booking.ended_at is not null
       and v_booking.completed_at is null then
      -- Reward and booking flag were committed atomically by this RPC.
      return pg_catalog.jsonb_build_object(
        'success', true, 'already_cancelled', true,
        'cancellation_type', 'late', 'ticket_refunded', false,
        'partner_rewarded', true
      );
    end if;
    raise exception 'Cancelled booking has inconsistent refund or reward state.'
      using errcode = '23514';
  end if;

  if v_booking.status is distinct from 'confirmed'
     or v_booking.scheduled_at is null
     or v_booking.scheduled_at <= v_now then
    raise exception 'Only future confirmed bookings can be cancelled.'
      using errcode = '23514';
  end if;
  if v_booking.partner_user_id is null
     or v_booking.partner_id is distinct from v_booking.partner_user_id
     or v_booking.slot_id is null then
    raise exception 'Booking partner or slot is incomplete.' using errcode = '23514';
  end if;
  if v_booking.ticket_refunded is distinct from false
     or v_booking.partner_rewarded is distinct from false
     or v_booking.ended_at is not null
     or v_booking.completed_at is not null
     or nullif(pg_catalog.btrim(v_booking.end_reason), '') is not null
     or v_allocation.refunded_at is not null
     or v_allocation.refund_reason is not null then
    raise exception 'Booking has already entered a refund, reward or ending flow.'
      using errcode = '23514';
  end if;

  select * into v_slot
    from public.availability_slots
   where id = v_booking.slot_id
   for update;
  if not found or v_slot.status is distinct from 'booked'
     or v_slot.partner_id is distinct from v_booking.partner_user_id
     or v_slot.slot_time is null or v_slot.slot_time like 'weekly:%' then
    raise exception 'Booking availability slot is inconsistent.' using errcode = '23514';
  end if;
  if exists (
    select 1 from public.bookings b
     where b.slot_id = v_booking.slot_id
       and b.id <> p_booking_id
       and b.status = 'confirmed'
  ) then
    raise exception 'Another confirmed booking occupies this slot.' using errcode = '23514';
  end if;

  -- Recheck after the booking/slot locks: a wait can cross either boundary.
  v_now := pg_catalog.clock_timestamp();
  if v_booking.scheduled_at <= v_now then
    raise exception 'Only future confirmed bookings can be cancelled.'
      using errcode = '23514';
  end if;
  v_early := v_booking.scheduled_at > v_now + interval '6 hours';
  if v_early then
    -- Match lot-writer lock order: profile before lot. Original expiry stays.
    perform 1 from public.profiles where id = v_actor_id for update;
    if not found then
      raise exception 'Learner profile not found.' using errcode = 'P0002';
    end if;
    select * into v_lot from public.ticket_lots
     where id = v_allocation.ticket_lot_id for update;
    if not found or v_lot.user_id is distinct from v_actor_id
       or v_lot.quantity_remaining >= v_lot.quantity_issued then
      raise exception 'Original ticket lot cannot be restored.' using errcode = '23514';
    end if;
    update public.ticket_lots
       set quantity_remaining = quantity_remaining + 1,
           updated_at = v_now
     where id = v_lot.id and quantity_remaining < quantity_issued;
    if not found then
      raise exception 'Ticket lot changed during cancellation.' using errcode = '40001';
    end if;
    update public.ticket_allocations
       set refunded_at = v_now, refund_reason = 'user_cancelled_early'
     where id = v_allocation.id and refunded_at is null;
    if not found then
      raise exception 'Ticket allocation changed during cancellation.' using errcode = '40001';
    end if;
    v_ticket_count := public.refresh_ticket_balance_cache(v_actor_id);
  else
    -- A late cancellation is not session completion. Reuse only the existing
    -- partner identity/role, 6,000P amount, profile lock and booking flag.
    select point_balance into v_partner_points
      from public.profiles
     where id = v_booking.partner_user_id and role = 'partner'
     for update;
    if not found then
      raise exception 'Partner profile is required for late cancellation compensation.'
        using errcode = '23514';
    end if;
    update public.profiles
       set point_balance = coalesce(point_balance, 0) + 6000,
           updated_at = v_now
     where id = v_booking.partner_user_id and role = 'partner';
    if not found then
      raise exception 'Partner compensation could not be applied.' using errcode = '40001';
    end if;
  end if;

  update public.bookings
     set status = 'cancelled',
         end_reason = case when v_early then 'user_cancelled_early'
                           else 'user_cancelled_late' end,
         ended_at = v_now,
         ticket_refunded = v_early,
         partner_rewarded = not v_early,
         updated_at = v_now
   where id = p_booking_id and status = 'confirmed'
     and ticket_refunded = false and partner_rewarded = false;
  if not found then
    raise exception 'Booking changed during cancellation.' using errcode = '40001';
  end if;

  update public.availability_slots
     set status = 'available', updated_at = v_now
   where id = v_booking.slot_id
     and partner_id = v_booking.partner_user_id
     and status = 'booked';
  if not found then
    raise exception 'Availability slot changed during cancellation.' using errcode = '40001';
  end if;

  return pg_catalog.jsonb_build_object(
    'success', true, 'already_cancelled', false,
    'cancellation_type', case when v_early then 'early' else 'late' end,
    'ticket_refunded', v_early, 'partner_rewarded', not v_early,
    'ticket_count', v_ticket_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.dayo_valid_conversation_brief(p_brief jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  v_key text;
  v_purpose text;
  v_interest jsonb;
  v_interest_id text;
  v_seen text[] := array[]::text[];
begin
  if p_brief is null then
    return true;
  end if;
  if pg_catalog.jsonb_typeof(p_brief) <> 'object'
     or pg_catalog.octet_length(p_brief::text) > 2048 then
    return false;
  end if;

  for v_key in select pg_catalog.jsonb_object_keys(p_brief) loop
    if v_key not in ('purposes', 'interests', 'chat_style', 'chat_request', 'partner_preference') then
      return false;
    end if;
  end loop;

  if p_brief ? 'purposes' then
    if pg_catalog.jsonb_typeof(p_brief->'purposes') <> 'array' then
      return false;
    end if;
    if pg_catalog.jsonb_array_length(p_brief->'purposes') < 1
       or pg_catalog.jsonb_array_length(p_brief->'purposes') > 4 then
      return false;
    end if;
    for v_purpose in select pg_catalog.jsonb_array_elements_text(p_brief->'purposes') loop
      if v_purpose is null
         or v_purpose not in ('travel', 'opic', 'abroad', 'casual')
         or v_purpose = any(v_seen) then
        return false;
      end if;
      v_seen := pg_catalog.array_append(v_seen, v_purpose);
    end loop;
  end if;

  if p_brief ? 'interests' then
    if pg_catalog.jsonb_typeof(p_brief->'interests') <> 'array' then
      return false;
    end if;
    if pg_catalog.jsonb_array_length(p_brief->'interests') > 4 then
      return false;
    end if;
    v_seen := array[]::text[];
    for v_interest in select pg_catalog.jsonb_array_elements(p_brief->'interests') loop
      if pg_catalog.jsonb_typeof(v_interest) <> 'string' then
        return false;
      end if;
      v_interest_id := v_interest #>> '{}';
      if v_interest_id not in (
        'drama', 'movies', 'youtube', 'music', 'travel', 'food_cafe',
        'exercise', 'games', 'fashion_beauty', 'pets', 'books_webtoon', 'work_school'
      ) or v_interest_id = any(v_seen) then
        return false;
      end if;
      v_seen := pg_catalog.array_append(v_seen, v_interest_id);
    end loop;
  end if;
  if p_brief ? 'chat_style'
     and p_brief->'chat_style' <> 'null'::jsonb
     and (pg_catalog.jsonb_typeof(p_brief->'chat_style') <> 'string'
          or p_brief->>'chat_style' not in ('casual', 'correct', 'interview')) then
    return false;
  end if;
  if p_brief ? 'chat_request'
     and p_brief->'chat_request' <> 'null'::jsonb
     and (pg_catalog.jsonb_typeof(p_brief->'chat_request') <> 'string'
          or p_brief->>'chat_request' not in ('praise', 'gentle', 'encourage')) then
    return false;
  end if;
  if p_brief ? 'partner_preference'
     and p_brief->'partner_preference' <> 'null'::jsonb
     and (pg_catalog.jsonb_typeof(p_brief->'partner_preference') <> 'string'
          or p_brief->>'partner_preference' not in ('slow', 'fast', 'correct', 'korean')) then
    return false;
  end if;
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.confirm_booking_with_cutoff_cleanup(p_learner_id uuid, p_booking_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor_id uuid := auth.uid();
  v_booking public.bookings%rowtype;
  v_slot_time text;
  v_scheduled_at timestamptz;
begin
  if v_actor_id is null or p_learner_id is distinct from v_actor_id
     or p_booking_id is null then
    raise exception 'Learner booking access is required.' using errcode = '42501';
  end if;

  -- Serialize confirmation, retries and cleanup for this exact booking.
  select * into v_booking
    from public.bookings
   where id = p_booking_id
   for update;
  if not found then
    return pg_catalog.jsonb_build_object('success', false, 'code', 'booking_not_found',
      'message', '?덉빟 ?뺣낫瑜?李얠쓣 ???놁뒿?덈떎.');
  end if;
  if v_booking.learner_id is distinct from v_actor_id then
    raise exception 'Learner booking access is required.' using errcode = '42501';
  end if;

  -- Check before the ticket lookup as well: a cutoff-crossed pending row
  -- must not linger merely because confirmation reports another failure first.
  if v_booking.status = 'pending' and not public.dayo_can_bypass_booking_lead_time() then
    select pg_catalog.btrim(slot_time) into v_slot_time
      from public.availability_slots
     where id = v_booking.slot_id;
    if v_slot_time ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}'
       and v_slot_time not like 'weekly:%' then
      begin
        if v_slot_time ~* '(Z|[+-][0-9]{2}(:[0-9]{2}|[0-9]{2})?)$' then
          v_scheduled_at := v_slot_time::timestamptz;
        else
          v_scheduled_at := v_slot_time::timestamp at time zone 'Asia/Seoul';
        end if;
      exception when others then
        v_scheduled_at := null;
      end;
    end if;
    if v_scheduled_at is not null
       and v_scheduled_at < pg_catalog.clock_timestamp() + interval '4 hours' then
      delete from public.bookings b
       where b.id = p_booking_id
         and b.learner_id = v_actor_id
         and b.status = 'pending'
         and b.ticket_deducted = false
         and b.ticket_refunded = false
         and b.partner_rewarded = false
         and not exists (
           select 1 from public.ticket_allocations a where a.booking_id = b.id
         );
      if not found then
        raise exception 'Cutoff cleanup found an inconsistent pending booking.'
          using errcode = '23514';
      end if;
      return pg_catalog.jsonb_build_object('success', false,
        'code', 'booking_window_closed',
        'message', '?덉빟 媛???쒓컙??吏?ъ뼱?? ?ㅻⅨ ?쒓컙???좏깮??二쇱꽭??');
    end if;
  end if;

  begin
    return public.deduct_ticket_and_confirm_booking(p_learner_id, p_booking_id);
  exception when check_violation then
    -- This handler's subtransaction rolls back lot, allocation and cache writes
    -- made by confirmation before the 065 trigger rejected its status update.
    if sqlerrm <> 'New bookings require at least four hours before the session.' then
      raise;
    end if;

    -- Never delete a confirmed booking, an allocation or another user's row.
    delete from public.bookings b
     where b.id = p_booking_id
       and b.learner_id = v_actor_id
       and b.status = 'pending'
       and b.ticket_deducted = false
       and b.ticket_refunded = false
       and b.partner_rewarded = false
       and not exists (
         select 1 from public.ticket_allocations a where a.booking_id = b.id
       );
    if not found then
      raise exception 'Cutoff cleanup found an inconsistent pending booking.'
        using errcode = '23514';
    end if;

    return pg_catalog.jsonb_build_object('success', false,
      'code', 'booking_window_closed',
      'message', '?덉빟 媛???쒓컙??吏?ъ뼱?? ?ㅻⅨ ?쒓컙???좏깮??二쇱꽭??');
  end;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_admin_partner_capabilities(p_partner_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_languages text[];
  v_level text;
begin
  if auth.uid() is null or not public.dayo_is_admin() then
    raise exception 'Admin access is required.' using errcode = '42501';
  end if;
  if p_partner_id is null then
    raise exception 'A partner is required.' using errcode = '22023';
  end if;
  perform 1 from public.profiles where id = p_partner_id and role = 'partner';
  if not found then
    raise exception 'Partner profile not found.' using errcode = 'P0002';
  end if;

  select c.conversation_languages, c.korean_support_level
    into v_languages, v_level
    from public.partner_capabilities c
   where c.partner_id = p_partner_id;

  return pg_catalog.jsonb_build_object(
    'success', true,
    'conversation_languages', coalesce(v_languages, '{}'::text[]),
    'korean_support_level', v_level,
    'configured', pg_catalog.cardinality(coalesce(v_languages, '{}'::text[])) > 0
      and v_level is not null
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_partner_capabilities(p_partner_id uuid, p_conversation_languages text[], p_korean_support_level text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor_id uuid := auth.uid();
  v_languages text[];
begin
  if v_actor_id is null or not public.dayo_is_admin() then
    raise exception 'Admin access is required.' using errcode = '42501';
  end if;
  if p_partner_id is null then
    raise exception 'A partner is required.' using errcode = '22023';
  end if;
  if p_conversation_languages is null
     or pg_catalog.cardinality(p_conversation_languages) = 0
     or pg_catalog.cardinality(p_conversation_languages) > 4
     or pg_catalog.array_position(p_conversation_languages, null) is not null
     or not (p_conversation_languages <@ array['en', 'es', 'fr', 'ko']::text[]) then
    raise exception 'Invalid conversation languages.' using errcode = '22023';
  end if;
  if p_korean_support_level is not null
     and p_korean_support_level not in ('none', 'basic', 'conversational', 'fluent') then
    raise exception 'Invalid Korean support level.' using errcode = '22023';
  end if;
  if (select pg_catalog.count(*) from pg_catalog.unnest(p_conversation_languages) as u(language_code))
     <> (select pg_catalog.count(distinct u.language_code)
           from pg_catalog.unnest(p_conversation_languages) as u(language_code)) then
    raise exception 'Duplicate conversation language.' using errcode = '22023';
  end if;

  perform 1 from public.profiles where id = p_partner_id and role = 'partner' for update;
  if not found then
    raise exception 'Partner profile not found.' using errcode = 'P0002';
  end if;

  v_languages := p_conversation_languages;
  insert into public.partner_capabilities (
    partner_id, conversation_languages, korean_support_level, updated_by
  ) values (
    p_partner_id, v_languages, p_korean_support_level, v_actor_id
  )
  on conflict (partner_id) do update
    set conversation_languages = excluded.conversation_languages,
        korean_support_level = excluded.korean_support_level,
        updated_at = pg_catalog.now(),
        updated_by = excluded.updated_by;

  return pg_catalog.jsonb_build_object(
    'success', true,
    'conversation_languages', v_languages,
    'korean_support_level', p_korean_support_level,
    'configured', p_korean_support_level is not null
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.save_partner_profile_completion(p_details jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_location text; v_visa text; v_korean text; v_capacity text;
  v_country text; v_city text; v_city_other text; v_has_location boolean;
  v_native text[]; v_session text[];
  v_other jsonb; v_entry jsonb; v_language text; v_level text;
  v_seen text[] := '{}'::text[];
  v_result public.partner_profile_details;
begin
  if v_uid is null then raise exception 'Partner access required.' using errcode = '42501'; end if;
  perform 1 from public.profiles where id = v_uid and role = 'partner' for share;
  if not found then raise exception 'Partner access required.' using errcode = '42501'; end if;
  if p_details is null or jsonb_typeof(p_details) is distinct from 'object'
    or p_details -> 'guide_acknowledged' is distinct from 'true'::jsonb then
    raise exception 'Read and acknowledge the DayO Partner Guide.' using errcode = '22023';
  end if;
  v_location := p_details ->> 'location_status'; v_visa := p_details ->> 'visa_type';
  v_korean := p_details ->> 'korean_level'; v_capacity := p_details ->> 'weekly_session_capacity';
  if v_location is null or v_location not in ('korea','overseas')
    or v_visa is null or (v_location = 'korea' and v_visa not in ('D-2','D-4','F-series','Other visa'))
    or (v_location = 'overseas' and v_visa <> 'not_applicable_overseas')
    or v_korean is null or v_korean not in ('none','basic','conversational','advanced','native')
    or v_capacity is null or v_capacity not in ('1-2','3-5','6-10','10+') then
    raise exception 'Complete location, visa, Korean level and weekly capacity.' using errcode = '22023';
  end if;
  -- Do not rewrite completed legacy rows or require them to complete again.
  -- New clients send country/city. Old 081 clients omit both during rollout.
  v_has_location := p_details ? 'country' or p_details ? 'city';
  if v_has_location then
    v_country := btrim(p_details ->> 'country'); v_city := btrim(p_details ->> 'city');
    v_city_other := nullif(btrim(p_details ->> 'korea_city_other'),'');
    if v_country is null or length(v_country) not between 1 and 100
      or v_city is null or length(v_city) not between 1 and 100
      or (v_location = 'korea' and v_country <> 'South Korea')
      or (v_location = 'overseas' and lower(v_country) in ('korea','south korea','republic of korea','한국','대한민국'))
      or (v_city_other is not null and (v_location <> 'korea' or v_city_other <> v_city)) then
      raise exception 'Complete a valid country and city for your location.' using errcode = '22023';
    end if;
  end if;
  if jsonb_typeof(p_details -> 'native_languages') is distinct from 'array'
    or jsonb_typeof(p_details -> 'session_languages') is distinct from 'array'
    or jsonb_typeof(p_details -> 'other_languages') is distinct from 'array' then
    raise exception 'Invalid language selections.' using errcode = '22023';
  end if;
  if exists (select 1 from jsonb_array_elements(p_details -> 'native_languages') x where jsonb_typeof(x) <> 'string')
    or exists (select 1 from jsonb_array_elements(p_details -> 'session_languages') x where jsonb_typeof(x) <> 'string') then
    raise exception 'Selections must be text.' using errcode = '22023';
  end if;
  select array_agg(btrim(value)) into v_native from jsonb_array_elements_text(p_details -> 'native_languages');
  select array_agg(btrim(value)) into v_session from jsonb_array_elements_text(p_details -> 'session_languages');
  if coalesce(cardinality(v_native),0) not between 1 and 14
    or coalesce(cardinality(v_session),0) not between 1 and 28
    or exists (select 1 from unnest(v_native || v_session) l where l is null or length(l) not between 1 and 100)
    or cardinality(v_native) <> (select count(distinct lower(l)) from unnest(v_native) l)
    or cardinality(v_session) <> (select count(distinct lower(l)) from unnest(v_session) l) then
    raise exception 'Choose valid, distinct languages.' using errcode = '22023';
  end if;
  v_other := p_details -> 'other_languages';
  if jsonb_array_length(v_other) > 14 then raise exception 'Too many other languages.' using errcode = '22023'; end if;
  for v_entry in select value from jsonb_array_elements(v_other) loop
    v_language := btrim(v_entry ->> 'language'); v_level := v_entry ->> 'level';
    if jsonb_typeof(v_entry) <> 'object' or jsonb_typeof(v_entry -> 'language') is distinct from 'string'
      or v_language is null or length(v_language) not between 1 and 100
      or v_level is null or v_level not in ('basic','conversational','fluent','native')
      or lower(v_language) = any(v_seen)
      or exists (select 1 from unnest(v_native) l where lower(l) = lower(v_language)) then
      raise exception 'Invalid other language proficiency.' using errcode = '22023';
    end if;
    v_seen := array_append(v_seen,lower(v_language));
  end loop;
  if exists (select 1 from unnest(v_session) l where not (l = any(v_native)) and not exists (
    select 1 from jsonb_array_elements(v_other) o where btrim(o ->> 'language') = l and o ->> 'level' in ('conversational','fluent','native'))) then
    raise exception 'Session languages must be native or Conversational or higher.' using errcode = '22023';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('language',btrim(o ->> 'language'),'level',o ->> 'level')),'[]'::jsonb)
    into v_other from jsonb_array_elements(v_other) o;
  insert into public.partner_profile_details(partner_id,location_status,visa_type,country,city,korea_city_other,native_languages,other_languages,
    session_languages,korean_level,weekly_session_capacity,partner_guide_acknowledged_at,completed_at)
  values(v_uid,v_location,v_visa,v_country,v_city,v_city_other,v_native,v_other,v_session,v_korean,v_capacity,now(),now())
  on conflict (partner_id) do update set location_status = excluded.location_status, visa_type = excluded.visa_type,
    country = case when v_has_location then excluded.country else case when excluded.location_status = partner_profile_details.location_status then partner_profile_details.country else null end end,
    city = case when v_has_location then excluded.city else case when excluded.location_status = partner_profile_details.location_status then partner_profile_details.city else null end end,
    korea_city_other = case when v_has_location then excluded.korea_city_other else case when excluded.location_status = partner_profile_details.location_status then partner_profile_details.korea_city_other else null end end,
    native_languages = excluded.native_languages, other_languages = excluded.other_languages,
    session_languages = excluded.session_languages, korean_level = excluded.korean_level,
    weekly_session_capacity = excluded.weekly_session_capacity,
    partner_guide_acknowledged_at = coalesce(partner_profile_details.partner_guide_acknowledged_at,excluded.partner_guide_acknowledged_at),
    completed_at = coalesce(partner_profile_details.completed_at,excluded.completed_at), updated_at = now()
  returning * into v_result;
  return to_jsonb(v_result);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_booking_calendar_slots(p_partner_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_partner uuid;v_today date:=(clock_timestamp() at time zone 'Asia/Seoul')::date;v_result jsonb;
begin
  if auth.uid() is null then raise exception 'Login required' using errcode='42501';end if;
  if p_partner_ids is null or cardinality(p_partner_ids)>100 then raise exception 'Invalid partner selection' using errcode='22023';end if;
  for v_partner in select distinct p.id from public.profiles p where p.id=any(p_partner_ids) and p.role='partner' order by p.id loop
    perform public.refresh_partner_monthly_slots(v_partner,false);
  end loop;
  -- A single JSON result avoids PostgREST's default row cap truncating calendar dates.
  select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'partner_id',s.partner_id,'slot_time',s.slot_time,'status',s.status)
    order by public.availability_kst_start(s.slot_time),s.partner_id,s.id),'[]'::jsonb) into v_result
    from public.availability_slots s join public.profiles p on p.id=s.partner_id
    where s.partner_id=any(p_partner_ids) and p.role='partner' and s.status='available'
      and public.availability_kst_start(s.slot_time)>clock_timestamp()
      and (public.availability_kst_start(s.slot_time) at time zone 'Asia/Seoul')::date between v_today and v_today+29
      and not exists(select 1 from public.bookings b where b.partner_id=s.partner_id and b.status='confirmed' and b.scheduled_at=public.availability_kst_start(s.slot_time));
  return v_result;
end;
$function$
